#' Safety Surveillance (MaxSPRT)
#'
#' Maximized sequential probability ratio test for post-marketing safety 
#' surveillance (Kulldorff et al. 2011): Poisson (observed against expected 
#' counts) or binomial (cases in the risk window against the control window), 
#' continuous or group monitoring, with an exact critical value, signalling 
#' thresholds, power, expected time to signal and expected length of 
#' surveillance, and the test applied to cumulative counts.
#' @param data .
#' @param cases .
#' @param expected .
#' @param model .
#' @param alpha .
#' @param survLength .
#' @param N .
#' @param z .
#' @param M .
#' @param monitoring .
#' @param nLooks .
#' @param looks .
#' @param rr .
#' @param thresholdTable .
#' @param boundaryPlot .
#' @param powerPlot .
#' @return A results object containing:
#' \tabular{llllll}{
#'   \code{results$summary} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$performance} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$thresholds} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$monitor} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$boundaryPlot} \tab \tab \tab \tab \tab an image \cr
#'   \code{results$powerPlot} \tab \tab \tab \tab \tab an image \cr
#' }
#'
#' Tables can be converted to data frames with \code{asDF} or \code{\link{as.data.frame}}. For example:
#'
#' \code{results$summary$asDF}
#'
#' \code{as.data.frame(results$summary)}
#'
#' @export
maxsprt <- function(
    data,
    cases = NULL,
    expected = NULL,
    model = "poisson",
    alpha = 0.05,
    survLength = 20,
    N = 50,
    z = 1,
    M = 1,
    monitoring = "continuous",
    nLooks = 5,
    looks = "",
    rr = "1.5, 2, 3, 4",
    thresholdTable = TRUE,
    boundaryPlot = TRUE,
    powerPlot = FALSE) {

    if ( ! requireNamespace("jmvcore", quietly=TRUE))
        stop("maxsprt requires jmvcore to be installed (restart may be required)")

    if ( ! missing(cases)) cases <- jmvcore::resolveQuo(jmvcore::enquo(cases))
    if ( ! missing(expected)) expected <- jmvcore::resolveQuo(jmvcore::enquo(expected))
    if (missing(data))
        data <- jmvcore::marshalData(
            parent.frame(),
            `if`( ! missing(cases), cases, NULL),
            `if`( ! missing(expected), expected, NULL))


    options <- maxsprtOptions$new(
        cases = cases,
        expected = expected,
        model = model,
        alpha = alpha,
        survLength = survLength,
        N = N,
        z = z,
        M = M,
        monitoring = monitoring,
        nLooks = nLooks,
        looks = looks,
        rr = rr,
        thresholdTable = thresholdTable,
        boundaryPlot = boundaryPlot,
        powerPlot = powerPlot)

    analysis <- maxsprtClass$new(
        options = options,
        data = data)

    analysis$run()

    analysis$results
}

